-- =====================================================================
-- Aindgc · Schema (H2)
--
-- AUTO-GENERATED from 01-schema.sql (MySQL 8) by deploy/docker/tools/mysql2h2.mjs
-- Do not hand-edit: regenerate instead, or the two schemas will drift.
--
-- Differences vs the MySQL original, all intentional:
--   * inline KEY / UNIQUE KEY hoisted into standalone CREATE INDEX
--   * index names prefixed with the table name (H2 index names are schema-global,
--     MySQL's are per-table, and this schema reused uk_share / idx_user everywhere)
--   * BIGINT UNSIGNED AUTO_INCREMENT -> GENERATED BY DEFAULT AS IDENTITY
--   * JSON -> CLOB (mapped to String by the app; avoids H2 JSON parse strictness)
--   * MEDIUMTEXT / TEXT -> CLOB (H2 2.x has neither type)
--   * ON UPDATE CURRENT_TIMESTAMP dropped — MybatisPlusMetaObjectHandler stamps
--     updated_at on every update, so the behaviour is preserved
--   * inline column COMMENT dropped (H2 uses COMMENT ON COLUMN)
-- =====================================================================

-- ---------------------------------------------------------------------
-- User & Auth
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS t_user (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    username        VARCHAR(64)  NOT NULL,
    email           VARCHAR(128) NOT NULL,
    password_hash   VARCHAR(128) NOT NULL,
    nickname        VARCHAR(64)  NULL,
    avatar          VARCHAR(255) NULL,
    bio             VARCHAR(500) NULL,
    status          TINYINT      NOT NULL DEFAULT 1,
    last_login_at   DATETIME     NULL,
    last_login_ip   VARCHAR(64)  NULL,
    created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted         TINYINT      NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS t_user_uk_username ON t_user (username);
CREATE UNIQUE INDEX IF NOT EXISTS t_user_uk_email ON t_user (email);
CREATE INDEX IF NOT EXISTS t_user_idx_status ON t_user (status, deleted);

CREATE TABLE IF NOT EXISTS t_role (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    code            VARCHAR_IGNORECASE(32) NOT NULL,
    name            VARCHAR(64) NOT NULL,
    description     VARCHAR(255) NULL,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted         TINYINT NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS t_role_uk_code ON t_role (code);

CREATE TABLE IF NOT EXISTS t_permission (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    code            VARCHAR_IGNORECASE(64) NOT NULL,
    name            VARCHAR(64) NOT NULL,
    type            VARCHAR(16) NOT NULL DEFAULT 'API',
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted         TINYINT NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS t_permission_uk_code ON t_permission (code);

CREATE TABLE IF NOT EXISTS t_user_role (
    user_id         BIGINT NOT NULL,
    role_id         BIGINT NOT NULL,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, role_id)
);
CREATE INDEX IF NOT EXISTS t_user_role_idx_role ON t_user_role (role_id);

CREATE TABLE IF NOT EXISTS t_role_permission (
    role_id         BIGINT NOT NULL,
    permission_id   BIGINT NOT NULL,
    PRIMARY KEY (role_id, permission_id)
);
CREATE INDEX IF NOT EXISTS t_role_permission_idx_perm ON t_role_permission (permission_id);

