CREATE INDEX IF NOT EXISTS t_tool_usage_idx_tool_action ON t_tool_usage (tool_id, action, created_at);
CREATE INDEX IF NOT EXISTS t_tool_usage_idx_user ON t_tool_usage (user_id, created_at);

